{"function": "() => {
    const result = {};
    // Title
    result.title = document.querySelector('h1')?.innerText || document.title;
    // Channel info
    const channel = document.querySelector('ytd-video-owner-renderer');
    result.channelName = channel?.querySelector('#channel-name')?.innerText;
    result.subscribers = channel?.querySelector('#owner-sub-count')?.innerText;
    // View count and date
    const viewCount = document.querySelector('yt-view-count-renderer')?.innerText || 
                      document.querySelector('.view-count')?.innerText ||
                      document.querySelector('.watch-view-count')?.innerText;
    result.viewCount = viewCount;
    const date = document.querySelector('yt-formatted-string.style-scope.ytd-video-primary-info-renderer')?.innerText;
    result.date = date;
    // Description full
    const description = document.querySelector('ytd-video-description-renderer');
    result.description = description?.innerText;
    // Chapters
    const chapters = Array.from(document.querySelectorAll('ytd-timeline-supporting-text-renderer a')).map(a => ({
        text: a.innerText,
        timestamp: a.getAttribute('href')
    }));
    result.chapters = chapters;
    // Comments
    const commentSection = document.querySelector('ytd-comments');
    if (commentSection) {
        const comments = Array.from(commentSection.querySelectorAll('ytd-comment-renderer')).map(comment => {
            const author = comment.querySelector('#author-text')?.innerText;
            const content = comment.querySelector('#content-text')?.innerText;
            const likes = comment.querySelector('#vote-count-middle')?.innerText;
            const time = comment.querySelector('yt-formatted-string.published-time-text')?.innerText;
            return { author, content, likes, time };
        });
        result.comments = comments;
        result.commentCount = comments.length;
    } else {
        result.comments = [];
    }
    // All visible text (for completeness)
    result.allText = document.body.innerText;
    return result;
}"}

